// Extract and structure all AI pipeline results
const pipeline = $input.first().json.body || $input.first().json;

// Lead qualification from Luna
const qual = pipeline.qualification || {};
const score = pipeline.score || qual.score || 0;
const temperature = pipeline.temperature || (score >= 8 ? 'hot' : score >= 5 ? 'warm' : 'cold');

// Build GHL-ready tags
const tags = ['agent-os', 'ai-qualified', `${temperature}-lead`];
if (qual.service_needed) tags.push(qual.service_needed.toLowerCase().replace(/\s+/g, '-'));
if (score >= 8) tags.push('priority');

// Extract proposal highlights (first 500 chars for GHL note)
const proposalPreview = (pipeline.proposal || '').substring(0, 500);
const clientPlanPreview = (pipeline.clientPlan || '').substring(0, 500);

return [{
  json: {
    // Lead info (passthrough)
    leadName: pipeline.lead?.name || '',
    leadEmail: pipeline.lead?.email || '',
    leadPhone: pipeline.lead?.phone || '',
    leadSource: pipeline.lead?.source || 'n8n',

    // Luna's qualification
    score,
    temperature,
    serviceNeeded: qual.service_needed || pipeline.serviceNeeded || '',
    budgetRange: qual.budget_range || pipeline.budgetRange || '',
    timeline: qual.timeline || pipeline.timeline || '',
    nextStep: qual.next_step || pipeline.nextStep || '',
    recommendedPackage: qual.recommended_package || pipeline.recommendedPackage || '',
    qualificationNotes: qual.notes || '',

    // Tags for GHL
    tags,

    // Full outputs for storage
    proposalFull: pipeline.proposal || pipeline.fullOutputs?.rex || '',
    clientPlanFull: pipeline.clientPlan || pipeline.fullOutputs?.nova || '',
    proposalPreview,
    clientPlanPreview,

    // Session tracking
    sessionId: pipeline.sessionId || '',
    success: pipeline.success || false,
  }
}];
